// Decode raw body bytes to UTF-8 string and forward both binary + string
const input = $input.first();
let rawBodyString = '';
if (input.binary && input.binary.data && input.binary.data.data) {
  rawBodyString = Buffer.from(input.binary.data.data, 'base64').toString('utf-8');
} else if (typeof input.json.body === 'string') {
  rawBodyString = input.json.body;
} else if (input.json.body) {
  rawBodyString = JSON.stringify(input.json.body);
}
return [{ json: { ...input.json, rawBodyString }, binary: input.binary }];

// === ElevenLabs post_call_transcription handler (multi-clinic) ===
// HMAC verification is done by the upstream "HMAC Sign" Crypto node — n8n's
// task-runner sandbox blocks both require('crypto') and globalThis.crypto.subtle,
// so we delegate HMAC compute to the built-in Crypto node and just compare here.

const HMAC_ENABLED = true;

const input = $input.first();
const headers = input.json.headers || {};
const signature = headers['elevenlabs-signature'] || headers['ElevenLabs-Signature'] || '';
const computedLH = input.json.computedHmacLH || '';
const computedNM = input.json.computedHmacNM || '';

// === HMAC verification ===
if (HMAC_ENABLED && (computedLH || computedNM) && signature !== computedLH && signature !== computedNM) {
  return [{ json: { status: 'error', reason: 'Invalid signature', skip: true,
                    expectedLH: String(computedLH).slice(0,12), expectedNM: String(computedNM).slice(0,12),
                    got: String(signature).slice(0,12) } }];
}

// === Read body — already decoded by upstream "Decode Body" node ===
const rawBody = input.json.rawBodyString || (typeof input.json.body === 'string' ? input.json.body : JSON.stringify(input.json.body || {}));

let ev;
try {
  ev = JSON.parse(rawBody);
} catch (e) {
  return [{ json: { status: 'error', reason: 'Invalid JSON', skip: true, rawSnippet: rawBody.slice(0,200) } }];
}

// === Filter: only post_call_transcription ===
if (ev.type !== 'post_call_transcription') {
  return [{ json: { status: 'ignored', type: ev.type, skip: true } }];
}

const d = ev.data || {};
const meta = d.metadata || {};
const analysis = d.analysis || {};
const dc = analysis.data_collection_results || {};
const dyn = (d.conversation_initiation_client_data || {}).dynamic_variables || {};

// === Resolve clinic location ===
const AGENT_LOCATION_MAP = {};
const SOURCE = dyn.clinic_location || dc.clinic_location || AGENT_LOCATION_MAP[d.agent_id] || 'Unknown clinic';

// === Caller identity ===
const firstName = dyn.caller_first_name || dc.caller_first_name || 'Unknown';
const lastName  = dyn.caller_last_name  || dc.caller_last_name  || '';
const phone     = dyn.caller_phone      || dc.caller_phone      || '';
const fullName  = (firstName + ' ' + lastName).trim();

// === Call metadata ===
const durSecs = meta.call_duration_secs || 0;
const duration = `${Math.floor(durSecs / 60)}m ${durSecs % 60}s`;

// === Note ===
const note = dc.staff_notes || analysis.transcript_summary || '';

// === Native classification ===
const dept = (dc.routed_department || '').toLowerCase();
const meds = dc.pharmacy_medications || '';
const callIntent = dc.call_intent || '';

// === Format transcript ===
const turns = (d.transcript || []).map(t => ({
  role: t.role === 'agent' ? 'bot' : 'human',
  text: String(t.message || '').replace(/\s+/g, ' ').trim()
})).filter(t => t.text);

const merged = [];
for (const t of turns) {
  const last = merged[merged.length - 1];
  if (last && last.role === t.role) last.text += ' ' + t.text;
  else merged.push({ ...t });
}

const transcriptText = merged.map((t, i) => {
  const icon = t.role === 'bot' ? '🤖' : '👤';
  return `${i + 1}. ${icon} ${t.text}`;
}).join('\n');

// === Routing flags ===
const isPharmacy = dept === 'pharmacy' || dept === 'human_pharmacy' || !!meds;
const isInquiry  = dept === 'care_questions';

// After-hours flag
const isAfterHoursRaw = String(dyn.is_after_hours ?? dc.is_after_hours ?? '').toLowerCase().trim();
const isAfterHours = isAfterHoursRaw === 'true' || isAfterHoursRaw === '1' || isAfterHoursRaw === 'yes';

// === Build payloads ===
const mainPayload = {
  text: `| Field | Details |\n|:--|:--|\n| Source | ${SOURCE} |\n| Patient Name | ${fullName} |\n| Phone | ${phone} |\n| Duration | ${duration} |\n| Note | ${note} |`,
  attachments: [{ color: '#0070f3', title: `📞 Transcript — ${SOURCE}`, text: transcriptText }]
};

const pharmacyPayload = isPharmacy ? {
  attachments: [{
    color: '#e74c3c',
    title: `💊 Pharmacy Request — Action Required (${SOURCE})`,
    text: '⚠️ Patient has a pharmacy request.',
    fields: [
      { title: 'Source', value: SOURCE, short: true },
      { title: 'Patient', value: fullName, short: true },
      { title: 'Phone', value: phone, short: true },
      { title: 'Request', value: callIntent || meds || 'See transcript', short: false },
      { title: 'Transcript', value: transcriptText, short: false }
    ]
  }]
} : null;

const inquiryPayload = isInquiry ? {
  attachments: [{
    color: '#27ae60',
    title: `❓ General Inquiry — Action Required (${SOURCE})`,
    text: '⚠️ Patient has a general inquiry.',
    fields: [
      { title: 'Source', value: SOURCE, short: true },
      { title: 'Patient', value: fullName, short: true },
      { title: 'Phone', value: phone, short: true },
      { title: 'Inquiry', value: callIntent || 'See transcript', short: false },
      { title: 'Transcript', value: transcriptText, short: false }
    ]
  }]
} : null;

const afterHoursPayload = isAfterHours ? {
  attachments: [{
    color: '#f39c12',
    title: `🌙 After-Hours Call — Callback Needed (${SOURCE})`,
    text: '⚠️ Call received outside business hours. Team must return this call.',
    fields: [
      { title: 'Source', value: SOURCE, short: true },
      { title: 'Patient', value: fullName, short: true },
      { title: 'Phone', value: phone, short: true },
      { title: 'Duration', value: duration, short: true },
      { title: 'Reason', value: callIntent || 'See transcript', short: false },
      { title: 'Note', value: note || '(no staff notes captured)', short: false },
      { title: 'Transcript', value: transcriptText, short: false }
    ]
  }]
} : null;


// === Extra fields for patient memory (Redis write-back) ===
const dcInsurance = dc.insurance_plan || dc.insurance || '';
const dcDob = dc.patient_dob || dc.dob || '';
const dcPharmacy = dc.preferred_pharmacy || dc.pharmacy || '';
const sentiment = dc.caller_sentiment || '';

return [{
  json: {
    status: 'ok', skip: false, source: SOURCE,
    conversationId: d.conversation_id || '',
    fullName, firstName, lastName, phone, duration, note, dept, meds, callIntent,
    dcInsurance, dcDob, dcPharmacy, sentiment,
    isPharmacy, isInquiry, isAfterHours,
    mainPayload, pharmacyPayload, inquiryPayload, afterHoursPayload
  }
}];

// === Merge this call's data into the stored patient profile ===
const ve = $('Validate & Extract').item.json;
const phone = ve.phone || '';
if (!phone) { return [{ json: { skipWrite: true } }]; }

// existing profile (may be empty)
let prof = {};
try {
  const raw = $json.existingProfileRaw;
  if (raw && typeof raw === 'string') prof = JSON.parse(raw);
  else if (raw && typeof raw === 'object' && raw !== null) prof = raw;
} catch (e) { prof = {}; }

// helper: only overwrite if the new value is non-empty (never wipe known data with blanks)
const set = (k, v) => { if (v !== undefined && v !== null && String(v).trim() !== '') prof[k] = String(v).trim(); };

set('first_name', ve.firstName);
set('last_name', ve.lastName);
prof.caller_phone = phone;
set('insurance_plan', ve.dcInsurance);
set('dob', ve.dcDob);
set('preferred_pharmacy', ve.dcPharmacy);
set('known_medications', ve.meds);
set('clinic_location', ve.source);
// always-updated "last call" fields
prof.last_call_reason = ve.callIntent || ve.dept || prof.last_call_reason || '';
prof.last_call_summary = ve.note || prof.last_call_summary || '';
prof.last_call_date = (ve.mainPayload ? '' : '');  // set below from now via current date var
prof.last_call_sentiment = ve.sentiment || '';
prof.is_existing_patient = 'true';
prof.updated_at = new Date().toISOString();
// derive date (YYYY-MM-DD) in Miami time
prof.last_call_date = new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());

// call-history entry
const callEntry = JSON.stringify({
  date: prof.last_call_date,
  reason: prof.last_call_reason,
  summary: prof.last_call_summary,
  dept: ve.dept || '',
  sentiment: ve.sentiment || '',
  clinic: ve.source || '',
  conversationId: ve.conversationId || ''
});

return [{ json: {
  skipWrite: false,
  redisKey: 'patient:' + phone,
  redisCallsKey: 'patient:' + phone + ':calls',
  profileJson: JSON.stringify(prof),
  callEntry
}}];

